#!/usr/bin/env python3
"""Run qmllint against the QML module generated by CXX-Qt."""

from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "packaging"))

from metadata import ROOT as REPOSITORY_ROOT, cargo_target_directory, load_metadata, qt_query, qt_tool


def qml_sources(root: Path) -> set[str]:
    return {str(path.relative_to(root)) for path in (root / "ui/qml").rglob("*.qml")}


def stage_module(root: Path, module: Path, destination: Path, sources: set[str]) -> Path:
    module_path = destination / Path(*load_metadata()["app-id"].split("."))
    module_path.mkdir(parents=True)

    for source in sources:
        shutil.copyfile(root / source, module_path / Path(source).name)
    shutil.copyfile(module / "plugin.qmltypes", module_path / "plugin.qmltypes")

    lines = []
    for line in (module / "qmldir").read_text(encoding="utf-8").splitlines():
        if line.startswith("prefer "):
            continue
        if line.endswith(".qml"):
            tokens = line.split()
            tokens[-1] = Path(tokens[-1]).name
            line = " ".join(tokens)
        lines.append(line)
    (module_path / "qmldir").write_text("\n".join(lines) + "\n", encoding="utf-8")

    return module_path


def run() -> int:
    root = REPOSITORY_ROOT / "crates/kp-desktop"
    sources = qml_sources(root)
    module_path = Path(*load_metadata()["app-id"].split("."))
    module = cargo_target_directory() / "cxxqt/qml_modules" / module_path
    qmldir = module / "qmldir"
    registered = {
        line.split()[-1]
        for line in qmldir.read_text(encoding="utf-8").splitlines()
        if line.endswith(".qml")
    }

    if sources != registered:
        missing = sorted(sources - registered)
        stale = sorted(registered - sources)
        raise SystemExit(f"QML registration mismatch: missing={missing}, stale={stale}")
    if len({Path(source).name for source in sources}) != len(sources):
        raise SystemExit("QML components need distinct filenames for lint staging")

    with tempfile.TemporaryDirectory(prefix="kryptopass-qmllint-") as temporary:
        imports = Path(temporary)
        staged = stage_module(root, module, imports, sources)
        # The module is imported as Backend alongside its local QML types;
        # Qt 6.12 reports those names as renamed types.
        result = subprocess.run(
            [
                qt_tool("qmllint"),
                "--max-warnings",
                "0",
                "--renamed-type",
                "disable",
                "-I",
                str(imports),
                "-I",
                qt_query("QT_INSTALL_QML"),
                *map(str, sorted(staged.glob("*.qml"))),
            ],
            capture_output=True,
            text=True,
        )
        for stream, diagnostic in ((sys.stdout, result.stdout), (sys.stderr, result.stderr)):
            for source in sources:
                diagnostic = diagnostic.replace(
                    str(staged / Path(source).name), str(root / source)
                )
            stream.write(diagnostic)
        return result.returncode


if __name__ == "__main__":
    raise SystemExit(run())
